package fr.atelierdugoblin.mobile;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import android.Manifest;import android.content.pm.PackageManager;import android.webkit.JavascriptInterface;import org.json.*;import java.time.*;import java.util.*;
/** Private on-device expiry alarms. No network or background PC connection required. */
public final class FoodReminderBridge {
 final Activity activity;FoodReminderBridge(Activity a){activity=a;}
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("goblin-food-expiry-v1",Context.MODE_PRIVATE);}
 @JavascriptInterface public boolean sync(String raw){try{if(raw==null||raw.length()>2000000)return false;JSONArray rows=new JSONArray(raw);if(rows.length()>2000)return false;for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!r.getString("key").matches("[A-Za-z0-9_-]{1,100}")||r.getString("name").length()>120)return false;String date=r.optString("expiry_date","");if(!date.isEmpty()&&!date.equals("null"))LocalDate.parse(date);}prefs(activity).edit().putString("rows",raw).commit();resume(activity);return true;}catch(Exception e){return false;}}
 @JavascriptInterface public void requestPermission(){if(Build.VERSION.SDK_INT>=33&&activity.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)activity.runOnUiThread(()->activity.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},504));}
 static PendingIntent pending(Context c,String key,int days,long at,String name){Intent i=new Intent(c,FoodReminderReceiver.class).setAction("fr.atelierdugoblin.FOOD").setData(Uri.parse("goblin-food://alarm/"+key+"/"+days)).putExtra("at",at).putExtra("name",name).putExtra("days",days);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void resume(Context c){try{AlarmManager alarms=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);JSONArray old=new JSONArray(prefs(c).getString("alarms","[]"));for(int i=0;i<old.length();i++){JSONObject r=old.getJSONObject(i);alarms.cancel(pending(c,r.getString("key"),r.getInt("days"),0,""));}
 JSONArray rows=new JSONArray(prefs(c).getString("rows","[]")),scheduled=new JSONArray();ArrayList<JSONObject> plans=new ArrayList<>();long now=System.currentTimeMillis();Set<String> delivered=new HashSet<>(prefs(c).getStringSet("delivered",new HashSet<>()));
 for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String value=r.optString("expiry_date","");if(value.isEmpty()||value.equals("null")||!r.optString("status","active").equals("active"))continue;LocalDate end=LocalDate.parse(value);for(int days:new int[]{3,2,0}){long at=end.minusDays(days).atTime(9,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();String key=r.getString("key")+"_"+value;if(at<now-86400000L||delivered.contains(key+":"+days))continue;plans.add(new JSONObject().put("key",key).put("days",days).put("at",Math.max(now+1500,at)).put("name",r.getString("name")));}}
 plans.sort((a,b)->Long.compare(a.optLong("at"),b.optLong("at")));for(JSONObject p:plans){if(scheduled.length()>=200)break;alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,p.getLong("at"),pending(c,p.getString("key"),p.getInt("days"),p.getLong("at"),p.getString("name")));scheduled.put(p);}prefs(c).edit().putString("alarms",scheduled.toString()).commit();}catch(Exception ignored){}}
}
